import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/search', methods=['POST'])
def search():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid input'}), 400

    search_content = data.get('search_content')
    search_filename = data.get('search_filename')
    search_dir = data.get('search_dir')

    if not isinstance(search_content, str) and search_content is not None:
        return jsonify({'error': 'search_content must be a string'}), 400
    if not isinstance(search_filename, str) and search_filename is not None:
        return jsonify({'error': 'search_filename must be a string'}), 400
    if not isinstance(search_dir, str) and search_dir is not None:
        return jsonify({'error': 'search_dir must be a string'}), 400

    # Prevent path traversal
    if search_dir:
        # Resolve the directory and ensure it's within /data
        base_path = os.path.abspath(os.path.join('/data', search_dir))
        if not base_path.startswith('/data'):
            return jsonify({'error': 'Invalid search_dir'}), 400
    else:
        base_path = '/data'

    # Normalize to use forward slashes for JSON output
    base_path = base_path.replace('\\', '/')

    matches = []

    try:
        for root, dirs, files in os.walk(base_path):
            for name in files:
                # Check filename
                if search_filename and not name.startswith(search_filename):
                    continue

                # Check content
                if search_content:
                    file_path = os.path.join(root, name)
                    try:
                        with open(file_path, 'rb') as f:
                            content = f.read()
                            if isinstance(search_content, str):
                                # Decode as UTF-8, ignore errors
                                content_str = content.decode('utf-8', errors='ignore')
                                if search_content not in content_str:
                                    continue
                            else:
                                # Binary match (exact bytes)
                                if search_content not in content:
                                    continue
                    except (PermissionError, OSError, UnicodeDecodeError):
                        continue

                # If we get here, it's a match
                matches.append(file_path.replace('\\', '/'))
    except (PermissionError, OSError):
        pass

    return jsonify({'files': matches}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
